'use client';

import {
    Building2,
    DollarSign,
    TrendingUp,
    TrendingDown,
    Users,
    Key,
    AlertTriangle,
    CreditCard,
    Plus,
    ArrowUpRight,
    MoreHorizontal
} from 'lucide-react';

// Metric Card Component
interface MetricCardProps {
    title: string;
    value: string | number;
    change?: number;
    changeLabel?: string;
    icon: React.ReactNode;
    color: 'indigo' | 'emerald' | 'amber' | 'rose' | 'cyan';
}

function MetricCard({ title, value, change, changeLabel, icon, color }: MetricCardProps) {
    const colorClasses = {
        indigo: 'from-indigo-500 to-purple-600 shadow-indigo-500/20',
        emerald: 'from-emerald-500 to-teal-600 shadow-emerald-500/20',
        amber: 'from-amber-500 to-orange-600 shadow-amber-500/20',
        rose: 'from-rose-500 to-pink-600 shadow-rose-500/20',
        cyan: 'from-cyan-500 to-blue-600 shadow-cyan-500/20',
    };

    const isPositive = change && change > 0;

    return (
        <div className="relative overflow-hidden rounded-2xl bg-white/5 border border-white/10 p-6 card-hover">
            {/* Background Gradient */}
            <div className={`absolute -top-10 -right-10 h-32 w-32 rounded-full bg-gradient-to-br ${colorClasses[color]} opacity-20 blur-2xl`} />

            <div className="relative">
                {/* Header */}
                <div className="flex items-center justify-between mb-4">
                    <div className={`flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br ${colorClasses[color]} shadow-lg`}>
                        {icon}
                    </div>
                    {change !== undefined && (
                        <div className={`flex items-center gap-1 rounded-full px-2 py-1 text-xs font-medium ${isPositive ? 'bg-emerald-500/10 text-emerald-400' : 'bg-rose-500/10 text-rose-400'
                            }`}>
                            {isPositive ? <TrendingUp className="h-3 w-3" /> : <TrendingDown className="h-3 w-3" />}
                            {Math.abs(change)}%
                        </div>
                    )}
                </div>

                {/* Value */}
                <div className="mb-1">
                    <span className="text-3xl font-bold text-white">{value}</span>
                </div>

                {/* Label */}
                <p className="text-sm text-gray-400">{title}</p>
                {changeLabel && (
                    <p className="text-xs text-gray-500 mt-1">{changeLabel}</p>
                )}
            </div>
        </div>
    );
}

// Quick Action Button
interface QuickActionProps {
    icon: React.ReactNode;
    label: string;
    onClick?: () => void;
}

function QuickAction({ icon, label, onClick }: QuickActionProps) {
    return (
        <button
            onClick={onClick}
            className="flex items-center gap-3 w-full rounded-xl bg-white/5 border border-white/10 p-4 hover:bg-white/10 hover:border-indigo-500/50 transition-all duration-200 group"
        >
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-indigo-500/10 text-indigo-400 group-hover:bg-indigo-500 group-hover:text-white transition-colors">
                {icon}
            </div>
            <span className="text-sm font-medium text-gray-300 group-hover:text-white">{label}</span>
        </button>
    );
}

// Recent Activity Item
interface ActivityItemProps {
    type: 'tenant' | 'license' | 'payment' | 'alert';
    title: string;
    description: string;
    time: string;
}

function ActivityItem({ type, title, description, time }: ActivityItemProps) {
    const iconMap = {
        tenant: <Building2 className="h-4 w-4" />,
        license: <Key className="h-4 w-4" />,
        payment: <DollarSign className="h-4 w-4" />,
        alert: <AlertTriangle className="h-4 w-4" />,
    };

    const colorMap = {
        tenant: 'bg-indigo-500/10 text-indigo-400',
        license: 'bg-cyan-500/10 text-cyan-400',
        payment: 'bg-emerald-500/10 text-emerald-400',
        alert: 'bg-amber-500/10 text-amber-400',
    };

    return (
        <div className="flex items-start gap-3 py-3 border-b border-white/5 last:border-0">
            <div className={`flex h-8 w-8 items-center justify-center rounded-lg ${colorMap[type]} shrink-0`}>
                {iconMap[type]}
            </div>
            <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-white truncate">{title}</p>
                <p className="text-xs text-gray-400 truncate">{description}</p>
            </div>
            <span className="text-xs text-gray-500 shrink-0">{time}</span>
        </div>
    );
}

